  return { ok: title === 'LLM Knowledge Base' && intents.join(',') === 'Understand,Apply,Learn,Decode,Explore' && mode === 'spine' && top === 4, title, intents, mode, top, url: location.href };
})()`);
note('1-home', home);

// 2 Map via Explore
await ev(`(() => { const a = [...document.querySelectorAll('a.door')].find(el => el.querySelector('.door__intent')?.textContent.trim() === 'Explore'); a.click(); return true; })()`);
const map = await waitFor(`(() => {
  const title = document.querySelector('h1.map-head__title')?.textContent?.trim();
  const root = document.querySelector('[data-constellation-root]');
  const mapOn = [...document.querySelectorAll('a.kb-nav__link')].some(a => a.textContent.trim() === 'Map' && a.classList.contains('on'));
  const canvas = !!root?.querySelector('canvas');
