  const ok = location.pathname.includes('/wiki/Concepts/The-AI-Industrial-Revolution') && !!document.querySelector('article[data-pagefind-body]') && h1 === 'The AI Industrial Revolution' && pill === 'Concept' && !dek && crumb?.textContent.trim() === 'wiki' && crumb?.getAttribute('href') === '/folder/wiki/' && /more related pages$/.test(summary || '');
  return { ok, h1, pill, dek, crumb: crumb?.textContent?.trim(), href: crumb?.getAttribute('href'), summary, url: location.href };
})()`, 20000);
note('5-note', notePage);
const clicked = await ev(`(() => {
  const a = [...document.querySelectorAll('.kb-prose a')].find(el => !el.closest('details.kb-related-more') && el.textContent.trim());
  const text = a?.textContent?.trim();
  const href = a?.getAttribute('href');
  a?.click();
  return { text, href };
})()`);
const next = await waitFor(`(() => {
  const h1 = document.querySelector('h1.kb-note-title')?.textContent?.trim();
